// Synthetic screen -> selected subject -> normal activation/decision -> C5.
fn setup_dynamic_execution_fixture(s:&crate::service::TradeAssemblyService,root:&std::path::Path,refresh:bool,automatic:bool)->(InstalledPluginPackage,std::thread::JoinHandle<()>){
 let package=install_screen_package(s,root);s.runtime().plugins.put_instance(&package.plugin_ref,json!({"instanceRef":package.plugin_ref,"pluginRef":package.plugin_ref,"providerRef":package.plugin_ref,"enabled":true,"activePackageSha256":package.package_sha256,"configuration":{}}),&ctx("dynamic-screen-instance")).unwrap();
 let listener=TcpListener::bind("127.0.0.1:0").unwrap();let address=listener.local_addr().unwrap();
 let server=std::thread::spawn(move||{for index in 0..if automatic{3}else if refresh{2}else{1}{let(mut stream,_)=listener.accept().unwrap();let mut buffer=[0;8192];let n=stream.read(&mut buffer).unwrap();let calendar=String::from_utf8_lossy(&buffer[..n]).starts_with("GET /options ");assert!(calendar||String::from_utf8_lossy(&buffer[..n]).starts_with("GET /observations "));if calendar{assert!(automatic);let now=chrono::Utc::now().timestamp_millis();let date=chrono::DateTime::from_timestamp_millis(now).unwrap().date_naive().to_string();let document=json!({"schemaVersion":"tradeassembly.session_calendar.v1","calendarRef":"fixture.exchange","timeZone":"Etc/UTC","sessionScope":"fixture_primary","revision":"fixture.auto.v1","rangeStart":date,"rangeEnd":date,"knownAtMs":now,"days":[{"sessionDate":date,"session":{"status":"open","openAtMs":now-1000,"closeAtMs":now+3600000,"earlyClose":false}}]});let bytes=serde_json::to_vec(&document).unwrap();write!(stream,"HTTP/1.1 200 OK\r\nContent-Length: {}\r\nConnection: close\r\n\r\n",bytes.len()).unwrap();stream.write_all(&bytes).unwrap();continue;}let rows=if !refresh||index==0{json!([{"id":"SPY","dte":50,"oi":20,"oiAgeDays":0},{"id":"B","dte":50,"oi":10,"oiAgeDays":0}])}else{json!([{"id":"SPY","dte":50,"oi":10,"oiAgeDays":0},{"id":"B","dte":50,"oi":20,"oiAgeDays":0}])};let bytes=serde_json::to_vec(&json!({"rows":rows,"coverage":{"complete":true,"scope":"fixture_candidates"}})).unwrap();write!(stream,"HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n",bytes.len()).unwrap();stream.write_all(&bytes).unwrap();}});
 let mut replay=s.runtime().plugins.get_instance("capture.source").unwrap().unwrap();replay["configuration"]=json!({"dataApiUrl":format!("http://{address}")});replay["credentialRef"]=json!("dynamic-screen-fake-source");s.runtime().plugins.put_instance("capture.source",replay,&ctx("dynamic-source-config")).unwrap();s.runtime().credentials.store("dynamic-screen-fake-source",&BTreeMap::from([("api_key".into(),"fake-screen-only-key".into()),("api_secret".into(),"fake-screen-only-secret".into())])).unwrap();
 (package,server)
}
